const PDFParser = require('pdf2json');
const fs = require('fs');
const parser = new PDFParser(null, 1);
const out = [];
parser.on('pdfParser_dataError', e => { console.error(JSON.stringify({error:e.parserError})); process.exit(1); });
parser.on('pdfParser_dataReady', data => {
  for (const [i, page] of (data.Pages||[]).entries()) {
    const txt = (page.Texts||[]).map(t=>(t.R||[]).map(r=>{ try{return decodeURIComponent(r.T);}catch{return r.T;} }).join('')).filter(s=>s.trim()).join(' ').replace(/\\s+/g,' ').trim();
    out.push({page:i+1,text:txt});
  }
  fs.writeFileSync(process.env.WAVLON_ASSETS_PATH+'/blt-guide-data.json', JSON.stringify({title:'BLT Intelligent Laser Cutting Head Selection Guide',source:'https://d.fscut.com/wordpress-fscut/2024/03/BLT-Intelligent-Laser-Cutting-Head-Selection-Guide.pdf',extractedAt:new Date().toISOString(),totalPages:data.Pages?.length,pages:out},null,2));
  console.log(JSON.stringify({success:true,pages:out.length}));
});
parser.loadPDF(process.env.WAVLON_ASSETS_PATH+'/blt-selection-guide.pdf');
"

node -e "
const { createCanvas } = require('canvas');
const fs = require('fs');
const pdfjsLib = require('pdfjs-dist/legacy/build/pdf.cjs');
const assetsPath = process.env.WAVLON_ASSETS_PATH;
const outDir = assetsPath+'/blt-guide';
if(!fs.existsSync(outDir)) fs.mkdirSync(outDir,{recursive:true});
const pdfData = new Uint8Array(fs.readFileSync(assetsPath+'/blt-selection-guide.pdf'));
pdfjsLib.getDocument({data:pdfData,useWorkerFetch:false,isEvalSupported:false}).promise.then(async pdf=>{
  let count=0;
  for(let p=1;p<=pdf.numPages;p++){
    const page = await pdf.getPage(p);
    const ops = await page.getOperatorList();
    for(let i=0;i<ops.fnArray.length;i++){
      if(ops.fnArray[i]===pdfjsLib.OPS.paintImageXObject||ops.fnArray[i]===pdfjsLib.OPS.paintInlineImageXObject){
        try{
          const name=ops.argsArray[i][0];
          const imgData = await new Promise((res,rej)=>{ page.objs.get(name,d=>d?res(d):rej()); setTimeout(()=>rej(),2000); }).catch(()=>null);
          if(!imgData||!imgData.data||imgData.width<50) continue;
          count++;
          const {width,height,kind,data}=imgData;
          const canvas=createCanvas(width,height);
          const ctx=canvas.getContext('2d');
          const id=ctx.createImageData(width,height);
          if(kind===3){for(let j=0;j<Math.min(data.length,id.data.length);j++) id.data[j]=data[j];}
          else if(kind===2){for(let j=0,k=0;j<width*height;j++,k+=3){id.data[j*4]=data[k];id.data[j*4+1]=data[k+1];id.data[j*4+2]=data[k+2];id.data[j*4+3]=255;}}
          ctx.putImageData(id,0,0);
          const fname='blt-guide-p'+String(p).padStart(2,'0')+'-img'+String(count).padStart(2,'0')+'.png';
          fs.writeFileSync(outDir+'/'+fname,canvas.toBuffer('image/png'));
        }catch(e){}
      }
    }
  }
  console.log(JSON.stringify({success:true,imagesExtracted:count}));
});
"

